window.RP_SESSION={"id":"S-eb5bd782434d","messages":[{"id":"RP-II-0176892","time":"2026-08-31T22:21:00+09:00","room":"RP II","name":"미샤","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"미샤는 식물을 키워 작은 꽃을 피웠다.","characters":["P-41ba4c5736e6"]},{"id":"RP-II-0176893","time":"2026-08-31T22:21:00+09:00","room":"RP II","name":"미샤","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"조금은 익숙해진 것 같기도 하네요.\"","characters":["P-41ba4c5736e6"]},{"id":"RP-II-0176894","time":"2026-08-31T22:22:00+09:00","room":"RP II","name":"미샤","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"동물은 그저 원초적인 두려움을 심어 굴복시키면 된다. 하지만 식물을 다루는 것은 아직 어렵게만 느껴진다.","characters":["P-41ba4c5736e6"]},{"id":"RP-II-0176895","time":"2026-08-31T22:22:00+09:00","room":"RP II","name":"미샤","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"자연의 순환. 인과. 모든 것을 벗어나는 것 아닌가요?\"","characters":["P-41ba4c5736e6"]},{"id":"RP-II-0176896","time":"2026-08-31T22:23:00+09:00","room":"RP II","name":"미샤","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"식물이 자라는데는 오랜 시간이 필요하다. 다른 드루이드들처럼(길드의 드루이드 같지는 않을지 몰라도) 넝쿨을 자라게 하거나 하면 좀 편하련만...","characters":["P-41ba4c5736e6"]},{"id":"RP-II-0176897","time":"2026-08-31T22:24:00+09:00","room":"RP II","name":"미샤","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"원래 봄에 피워야하는 꽃이 늦여름에 피었다.","characters":["P-41ba4c5736e6"]},{"id":"RP-II-0176898","time":"2026-08-31T22:24:00+09:00","room":"RP II","name":"미샤","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"물론 자연력을 몰아줘서 그 기운에 자연이 충만하지만 이것은 일반적인 그런 것은 아니다.","characters":["P-41ba4c5736e6"]},{"id":"RP-II-0176899","time":"2026-08-31T22:25:00+09:00","room":"RP II","name":"미샤","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"하지만...\"","characters":["P-41ba4c5736e6"]},{"id":"RP-II-0176900","time":"2026-08-31T22:25:00+09:00","room":"RP II","name":"미샤","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"하지만 미샤는 분명 꽃을 피웠다. 스스로 혼란스러워하는 방향성이지만 결과는 정직하게 나타났다.","characters":["P-41ba4c5736e6"]},{"id":"RP-II-0176901","time":"2026-08-31T22:26:00+09:00","room":"RP II","name":"미샤","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"...\"","characters":["P-41ba4c5736e6"]},{"id":"RP-II-0176902","time":"2026-08-31T22:26:00+09:00","room":"RP II","name":"미샤","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"미샤는 꽃을 보면서 고민한다.","characters":["P-41ba4c5736e6"]},{"id":"RP-II-0176903","time":"2026-08-31T22:38:00+09:00","room":"RP II","name":"미샤","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"고민은 계속 깊어진다.","characters":["P-41ba4c5736e6"]},{"id":"RP-II-0176904","time":"2026-08-31T22:39:00+09:00","room":"RP II","name":"미샤","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-41ba4c5736e6"]},{"id":"RP-II-0176905","time":"2026-08-31T22:39:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
